#nullable enable // autogenerated

using System.IO;
using System.Threading.Tasks;
using Cysharp.Threading.Tasks;
using MVZ2.Managers;
using MVZ2.Resources;

namespace MVZ2.ResourcePacks
{
    public class BuiltinResourcePackReference : ResourcePackReference
    {
        public override bool IsBuiltin => true;
        public override bool Equals(object obj)
        {
            return obj is BuiltinResourcePackReference;
        }
        public override int GetHashCode()
        {
            return base.GetHashCode();
        }
        public override string GetKey()
        {
            return "builtin*";
        }
        public override string GetFileName()
        {
            return "builtin";
        }
        public override async UniTask<ResourcePackMetadata?> LoadMetadata(MainManager main)
        {
            var bytes = await main.ResourcePackManager.LoadBuiltinBytes();
            var reader = new ResourcePackMetadataReader(main);
            using var memoryStream = new MemoryStream(bytes);
            var loader = new ResourceLoaderZip(memoryStream, GetFileName());
            return await reader.ReadMetadata(loader, GetKey());
        }
        public override async UniTask<ResourcePack?> LoadPack(MainManager main, int dataVersion)
        {
            var bytes = await main.ResourcePackManager.LoadBuiltinBytes();
            var reader = ResourcePackReaderFactory.Create(main, dataVersion);
            using var memoryStream = new MemoryStream(bytes);
            var loader = new ResourceLoaderZip(memoryStream, GetFileName());
            return await reader.ReadPack(loader, GetKey());
        }
        public override async UniTask<bool> Export(MainManager main, string destPath)
        {
            var bytes = await main.ResourcePackManager.LoadBuiltinBytes();
            File.WriteAllBytes(destPath, bytes);
            return true;
        }
        public override bool Delete()
        {
            return false;
        }
    }
}
